  import express, { Express } from 'express';
  import { UseCases } from './compositionRoot';
  import { errorHandler } from './errorHandler';
  import { ProjectController } from './ProjectController';
  import { TaskController } from './TaskController';
  import { UserController } from './UserController';

  export function createApp(useCases: UseCases): Express {
    const users = new UserController(useCases.createUser);
    const projects = new ProjectController(useCases.createProject);
    const tasks = new TaskController(
      useCases.createTask,
      useCases.listTasks,
      useCases.assignTask,
      useCases.markTaskDone,
    );

    const app = express();
    app.use(express.json());

    app.post('/users', users.create);
    app.post('/projects', projects.create);
    app.post('/projects/:projectId/tasks', tasks.create);
    app.get('/projects/:projectId/tasks', tasks.list);
    app.put('/projects/:projectId/tasks/:taskId/assignee', tasks.assign);
    app.post('/projects/:projectId/tasks/:taskId/done', tasks.done);

    app.use(errorHandler);
    return app;
  }

